-- Read-only; exact identity, strict prior date, 30 calendar days. All-team comparison is diagnostic only.
with r as (select t.game_pk,t.game_date,t.team,t.batter, jsonb_build_array(t.pa_30d,t.ab_30d,t.hits_30d,t.singles_30d,t.doubles_30d,t.triples_30d,t.hr_30d,t.walks_30d,t.strikeouts_30d,t.batted_balls_30d,t.hard_hits_30d,t.barrels_30d,t.ev_sum_30d,t.ev_n_30d) stored,jsonb_build_array(coalesce(sum(b.pa) filter(where b.team=t.team),0),coalesce(sum(b.ab) filter(where b.team=t.team),0),coalesce(sum(b.hits) filter(where b.team=t.team),0),coalesce(sum(b.singles) filter(where b.team=t.team),0),coalesce(sum(b.doubles) filter(where b.team=t.team),0),coalesce(sum(b.triples) filter(where b.team=t.team),0),coalesce(sum(b.hr) filter(where b.team=t.team),0),coalesce(sum(b.walks) filter(where b.team=t.team),0),coalesce(sum(b.strikeouts) filter(where b.team=t.team),0),coalesce(sum(b.batted_balls) filter(where b.team=t.team),0),coalesce(sum(b.hard_hits) filter(where b.team=t.team),0),coalesce(sum(b.barrels) filter(where b.team=t.team),0),coalesce(sum(b.ev_sum) filter(where b.team=t.team),0),coalesce(sum(b.ev_n) filter(where b.team=t.team),0)) rebuilt,jsonb_build_array(coalesce(sum(b.pa),0),coalesce(sum(b.hits),0),coalesce(sum(b.walks),0),coalesce(sum(b.hr),0)) all_team, min(b.game_date) filter(where b.team=t.team) min_date,max(b.game_date) filter(where b.team=t.team) max_date, array_agg(b.game_pk order by b.game_date,b.game_pk) filter(where b.team=t.team) source_games,md5(string_agg(row_to_json(b)::text,'|' order by b.game_date,b.game_pk,b.team) filter(where b.team=t.team)) source_digest from public.mlb_totals_v11e_projected_lineup_players_2025_v1 t left join public.mlb_ml_xyear_batter_game_v1 b on b.season=2025 and b.batter=t.batter and b.game_date>=t.game_date-30 and b.game_date<t.game_date group by t.game_pk,t.game_date,t.team,t.batter,t.pa_30d,t.ab_30d,t.hits_30d,t.singles_30d,t.doubles_30d,t.triples_30d,t.hr_30d,t.walks_30d,t.strikeouts_30d,t.batted_balls_30d,t.hard_hits_30d,t.barrels_30d,t.ev_sum_30d,t.ev_n_30d) select jsonb_agg(jsonb_build_array(game_pk,game_date,team,batter,stored,rebuilt,all_team,min_date,max_date,source_games,source_digest) order by game_date,game_pk,team,batter) rows from r
